proof.command:
node --max-old-space-size=768 --input-type=module -e 'import fs from '\''node:fs'\'';import{sha256,taskContractDigest}from'\''./scripts/remediation/board.mjs'\'';
const d=JSON.parse(fs.readFileSync('\''docs/remediation/tracker.json'\'','\''utf8'\'')),t=d.tasks.find(t=>t.id==='\''W03.06'\''),b=JSON.parse(fs.readFileSync('\''docs/remediation/design/W03.06/baseline.json'\'','\''utf8'\''));
if(d.journal.length!==1000||t.state!=='\''in_progress'\''||d.tasks.filter(t=>['\''in_progress'\'','\''verification'\''].includes(t.state)).length!==1)throw Error('\''state'\'');
if(sha256(fs.readFileSync(t.preflight.plan.path))!==t.preflight.plan.sha256||taskContractDigest(t)!==t.preflight.contract_digest)throw Error('\''contract'\'');
const start=d.journal.findLast(e=>e.task_id===t.id&&e.to==='\''in_progress'\'');if(JSON.stringify(start.plan_snapshot)!==JSON.stringify(t.preflight))throw Error('\''start'\'');
