const auth=d.authority.local_authorization.record;if(sha256(fs.readFileSync(auth.path))!==auth.sha256)throw Error('\''mandate'\'');
for(const p of b.pins)if(sha256(fs.readFileSync(p.path))!==p.sha256)throw Error('\''pin '\''+p.path);
for(const prior of d.tasks.filter(t=>t.state==='\''closed'\''))for(const p of prior.artifact.files)if(sha256(fs.readFileSync(p.path))!==p.sha256)throw Error('\''accepted dependency '\''+p.path);
console.log(JSON.stringify({at:new Date().toISOString(),task:t.id,journal:d.journal.length,plan:t.preflight.plan,contract:t.preflight.contract_digest,start_snapshot:'\''exact'\'',authority:'\''local W03 only'\'',pins:b.pins.length,protected:b.pins.length-b.owned.length,accepted_dependencies:'\''unchanged'\'',result:'\''pass'\''}));'
